-- ============================================================
-- MODULE: AUTH
-- ============================================================

-- Core user entity
CREATE TABLE users (
    id                UUID         NOT NULL DEFAULT gen_random_uuid(),
    username          VARCHAR(30)  NOT NULL,
    email             VARCHAR(255) NOT NULL,
    display_name      VARCHAR(100),
    bio               TEXT,
    avatar_url        TEXT,
    website_url       TEXT,
    role              user_role    NOT NULL DEFAULT 'user',
    status            user_status  NOT NULL DEFAULT 'active',
    is_private        BOOLEAN      NOT NULL DEFAULT FALSE,
    is_verified       BOOLEAN      NOT NULL DEFAULT FALSE,
    -- Denormalized counters (maintained by triggers)
    follower_count    INTEGER      NOT NULL DEFAULT 0,
    following_count   INTEGER      NOT NULL DEFAULT 0,
    post_count        INTEGER      NOT NULL DEFAULT 0,
    -- Timestamps
    created_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    deleted_at        TIMESTAMPTZ,
    banner_url        TEXT,
    -- Administrative visibility (V56). Written through IpExtractor, which honours
    -- X-Forwarded-For only from a configured trusted proxy.
    registration_ip   INET,
    last_login_ip     INET,
    -- Advances on a real login only, never on a token refresh
    last_login_at     TIMESTAMPTZ,
    -- Meaningful only while status = 'suspended'; NULL means indefinite
    suspended_until   TIMESTAMPTZ,
    -- Stamped into every access token at issuance and compared on every authenticated request
    -- (V58). Advancing it invalidates every token already issued to the account. Written only by
    -- the atomic increment in AdminUserRepository, never through the User entity.
    token_epoch       INTEGER      NOT NULL DEFAULT 0,
    verified_category VARCHAR(50),
    CONSTRAINT users_follower_count_check CHECK ((follower_count >= 0)),
    CONSTRAINT users_following_count_check CHECK ((following_count >= 0)),
    CONSTRAINT users_post_count_check CHECK ((post_count >= 0)),
    PRIMARY KEY (id),
    UNIQUE (email),
    UNIQUE (username)
);

-- Local credentials (email + password login)
-- password_hash is nullable to support OAuth-only users who have no local password
CREATE TABLE user_credentials (
    user_id           UUID        NOT NULL,
    password_hash     TEXT,
    email_verified    BOOLEAN     NOT NULL DEFAULT FALSE,
    email_verified_at TIMESTAMPTZ,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- OAuth provider accounts (Google, etc.)
-- Note: access_token, refresh_token, token_expires_at were dropped in V23 (drop_legacy_plaintext_credential_columns).
-- These columns will be re-added with encrypted storage when that feature is implemented.
CREATE TABLE oauth_accounts (
    id             UUID           NOT NULL DEFAULT gen_random_uuid(),
    user_id        UUID           NOT NULL,
    provider       oauth_provider NOT NULL,
    provider_id    VARCHAR(255)   NOT NULL,
    provider_email VARCHAR(255),
    created_at     TIMESTAMPTZ    NOT NULL DEFAULT NOW(),
    updated_at     TIMESTAMPTZ    NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    UNIQUE (provider, provider_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- JWT refresh tokens (stored as hash for security)
CREATE TABLE refresh_tokens (
    id         UUID         NOT NULL DEFAULT gen_random_uuid(),
    user_id    UUID         NOT NULL,
    token_hash TEXT         NOT NULL,
    device_id  VARCHAR(255),
    user_agent TEXT,
    ip_address INET,
    expires_at TIMESTAMPTZ  NOT NULL,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    UNIQUE (token_hash),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: USER PROFILE & SETTINGS
-- ============================================================

-- Per-user notification and privacy settings
CREATE TABLE user_settings (
    user_id                UUID        NOT NULL,
    -- Notification toggles
    notify_likes           BOOLEAN     NOT NULL DEFAULT TRUE,
    notify_comments        BOOLEAN     NOT NULL DEFAULT TRUE,
    notify_follows         BOOLEAN     NOT NULL DEFAULT TRUE,
    notify_mentions        BOOLEAN     NOT NULL DEFAULT TRUE,
    notify_messages        BOOLEAN     NOT NULL DEFAULT TRUE,
    -- Privacy
    show_activity_status   BOOLEAN     NOT NULL DEFAULT TRUE,
    allow_story_replies    BOOLEAN     NOT NULL DEFAULT TRUE,
    allow_message_requests BOOLEAN     NOT NULL DEFAULT TRUE,
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    suggestible            BOOLEAN     NOT NULL DEFAULT TRUE,
    PRIMARY KEY (user_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Device push notification tokens
CREATE TABLE push_tokens (
    id           UUID        NOT NULL DEFAULT gen_random_uuid(),
    user_id      UUID        NOT NULL,
    token        TEXT        NOT NULL,
    platform     VARCHAR(10) NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    last_used_at TIMESTAMPTZ,
    CONSTRAINT push_tokens_platform_check CHECK (((platform)::TEXT = ANY ((ARRAY['ios'::VARCHAR, 'android'::VARCHAR, 'web'::VARCHAR])::TEXT[]))),
    PRIMARY KEY (id),
    UNIQUE (token),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: SOCIAL GRAPH (Follow / Block)
-- ============================================================

-- Follow relationships (unidirectional, like Instagram)
CREATE TABLE follows (
    follower_id  UUID          NOT NULL,
    following_id UUID          NOT NULL,
    status       follow_status NOT NULL DEFAULT 'accepted',
    -- status = 'pending' when target account is private
    created_at   TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    CONSTRAINT follows_check CHECK ((follower_id <> following_id)),
    PRIMARY KEY (follower_id, following_id),
    FOREIGN KEY (follower_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (following_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Block relationships
CREATE TABLE blocks (
    blocker_id UUID        NOT NULL,
    blocked_id UUID        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT blocks_check CHECK ((blocker_id <> blocked_id)),
    PRIMARY KEY (blocker_id, blocked_id),
    FOREIGN KEY (blocked_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (blocker_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: MEDIA ASSETS (Cloudflare R2)
-- ============================================================

-- Decision: store full metadata (width, height, duration, blurhash)
-- Reasons:
--   1. Aspect ratio needed for responsive UI layout (no extra API call)
--   2. Video duration required for player rendering
--   3. Blurhash provides loading placeholder (same as Instagram)
--   4. Avoids repeated HEAD requests to CDN per render
CREATE TABLE media_assets (
    id          UUID         NOT NULL DEFAULT gen_random_uuid(),
    user_id     UUID         NOT NULL,
    storage_key TEXT         NOT NULL,
    cdn_url     TEXT         NOT NULL,
    media_type  media_type   NOT NULL,
    mime_type   VARCHAR(100) NOT NULL,
    file_size   BIGINT       NOT NULL,
    width       INTEGER,
    height      INTEGER,
    duration    INTEGER,
    blurhash    VARCHAR(100),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT media_assets_duration_check CHECK ((duration >= 0)),
    CONSTRAINT media_assets_file_size_check CHECK ((file_size > 0)),
    CONSTRAINT media_assets_height_check CHECK ((height > 0)),
    CONSTRAINT media_assets_width_check CHECK ((width > 0)),
    PRIMARY KEY (id),
    UNIQUE (storage_key),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: POST
-- ============================================================

CREATE TABLE posts (
    id                       UUID          NOT NULL DEFAULT gen_random_uuid(),
    user_id                  UUID          NOT NULL,
    caption                  TEXT,
    post_type                post_type     NOT NULL DEFAULT 'image',
    status                   post_status   NOT NULL DEFAULT 'published',
    -- Denormalized counters for read performance
    like_count               INTEGER       NOT NULL DEFAULT 0,
    comment_count            INTEGER       NOT NULL DEFAULT 0,
    save_count               INTEGER       NOT NULL DEFAULT 0,
    view_count               INTEGER       NOT NULL DEFAULT 0,
    -- Optional location metadata
    location_name            VARCHAR(255),
    latitude                 NUMERIC(10,8),
    longitude                NUMERIC(11,8),
    -- Timestamps
    created_at               TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    updated_at               TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    deleted_at               TIMESTAMPTZ,
    -- Status held before a moderation removal, so restore returns the post there instead of
    -- publishing it (V59). Non-null only while the post sits removed by moderation.
    status_before_moderation post_status,
    CONSTRAINT posts_comment_count_check CHECK ((comment_count >= 0)),
    CONSTRAINT posts_like_count_check CHECK ((like_count >= 0)),
    CONSTRAINT posts_save_count_check CHECK ((save_count >= 0)),
    CONSTRAINT posts_view_count_check CHECK ((view_count >= 0)),
    PRIMARY KEY (id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Post media items (supports carousel: multiple images/videos)
CREATE TABLE post_media (
    id             UUID        NOT NULL DEFAULT gen_random_uuid(),
    post_id        UUID        NOT NULL,
    media_asset_id UUID        NOT NULL,
    "position"     SMALLINT    NOT NULL DEFAULT 0,
    alt_text       TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    UNIQUE (post_id, "position"),
    FOREIGN KEY (media_asset_id) REFERENCES media_assets(id),
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
);

-- Post likes (compound PK = one like per user per post)
CREATE TABLE post_likes (
    user_id    UUID        NOT NULL,
    post_id    UUID        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, post_id),
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Post saves / bookmarks
CREATE TABLE post_saves (
    user_id    UUID        NOT NULL,
    post_id    UUID        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, post_id),
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Post caption edit history (append-only audit; rows are never updated or soft-deleted)
CREATE TABLE post_edit_history (
    id               UUID        NOT NULL DEFAULT gen_random_uuid(),
    post_id          UUID        NOT NULL,
    editor_id        UUID        NOT NULL,
    previous_caption TEXT,
    edited_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    FOREIGN KEY (editor_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: COMMENTS (Nested, Adjacency List + root_id + depth)
-- ============================================================

-- Design: Adjacency list with root_id + depth columns.
-- Strategy:
--   - parent_id  → immediate parent (standard adjacency list)
--   - root_id    → top-level comment ancestor (null if top-level)
--   - depth      → nesting level (0 = top-level, 1 = direct reply, ...)
--   - Depth capped at 10 to prevent runaway nesting.
--   - Retrieval of subtrees uses WITH RECURSIVE CTE (built into PostgreSQL).
--   - This is simpler than Closure Table while remaining maintainable
--     for a student team; sufficient for Instagram-style 2-level display.
CREATE TABLE comments (
    id                UUID        NOT NULL DEFAULT gen_random_uuid(),
    post_id           UUID        NOT NULL,
    user_id           UUID        NOT NULL,
    parent_id         UUID,
    root_id           UUID,
    depth             SMALLINT    NOT NULL DEFAULT 0,
    content           TEXT        NOT NULL,
    -- Denormalized counters
    like_count        INTEGER     NOT NULL DEFAULT 0,
    reply_count       INTEGER     NOT NULL DEFAULT 0,
    -- Timestamps
    created_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at        TIMESTAMPTZ,
    moderation_status VARCHAR(20) NOT NULL DEFAULT 'approved'::VARCHAR,
    -- Set by application code on a content edit only; NULL means never edited. Distinct from
    -- updated_at, which the row-level trigger moves whenever a counter changes.
    edited_at         TIMESTAMPTZ,
    admin_removed_at  TIMESTAMPTZ,
    CONSTRAINT comments_depth_check CHECK (((depth >= 0) AND (depth <= 10))),
    CONSTRAINT comments_like_count_check CHECK ((like_count >= 0)),
    CONSTRAINT comments_reply_count_check CHECK ((reply_count >= 0)),
    PRIMARY KEY (id),
    FOREIGN KEY (parent_id) REFERENCES comments(id) ON DELETE CASCADE,
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
    FOREIGN KEY (root_id) REFERENCES comments(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Comment likes
CREATE TABLE comment_likes (
    user_id    UUID        NOT NULL,
    comment_id UUID        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, comment_id),
    FOREIGN KEY (comment_id) REFERENCES comments(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Comment write idempotency: caches the first response per (user_id, idempotency_key).
CREATE TABLE comment_write_idempotency (
    id              UUID        NOT NULL DEFAULT gen_random_uuid(),
    user_id         UUID        NOT NULL,
    idempotency_key VARCHAR(64) NOT NULL,
    request_hash    VARCHAR(64) NOT NULL,
    response_body   JSONB,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    UNIQUE (user_id, idempotency_key),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: HASHTAG & TRENDING
-- ============================================================

CREATE TABLE hashtags (
    id          UUID           NOT NULL DEFAULT gen_random_uuid(),
    name        VARCHAR(100)   NOT NULL,
    post_count  INTEGER        NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ    NOT NULL DEFAULT NOW(),
    -- 'deleted' is a state, never a row removal: deleting the row cascades to post_hashtags and
    -- drives the post_count trigger over every post that used the tag.
    status      hashtag_status NOT NULL DEFAULT 'active',
    status_note TEXT,
    status_at   TIMESTAMPTZ,
    status_by   UUID,
    pinned_at   TIMESTAMPTZ,
    pinned_by   UUID,
    CONSTRAINT hashtags_pin_pair CHECK ((((pinned_at IS NULL) AND (pinned_by IS NULL)) OR (pinned_at IS NOT NULL))),
    CONSTRAINT hashtags_post_count_check CHECK ((post_count >= 0)),
    PRIMARY KEY (id),
    UNIQUE (name),
    FOREIGN KEY (pinned_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (status_by) REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE post_hashtags (
    post_id    UUID        NOT NULL,
    hashtag_id UUID        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (post_id, hashtag_id),
    FOREIGN KEY (hashtag_id) REFERENCES hashtags(id) ON DELETE CASCADE,
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
);

-- Trending snapshots: populated by a scheduled background job
CREATE TABLE hashtag_trending (
    hashtag_id   UUID        NOT NULL,
    period_start TIMESTAMPTZ NOT NULL,
    period_end   TIMESTAMPTZ NOT NULL,
    post_count   INTEGER     NOT NULL DEFAULT 0,
    rank         INTEGER,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (hashtag_id, period_start),
    FOREIGN KEY (hashtag_id) REFERENCES hashtags(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: STORY (24-hour Ephemeral)
-- ============================================================

CREATE TABLE stories (
    id               UUID        NOT NULL DEFAULT gen_random_uuid(),
    user_id          UUID        NOT NULL,
    media_asset_id   UUID        NOT NULL,
    story_type       story_type  NOT NULL DEFAULT 'image',
    caption          TEXT,
    view_count       INTEGER     NOT NULL DEFAULT 0,
    expires_at       TIMESTAMPTZ NOT NULL DEFAULT (NOW() + '24:00:00'::INTERVAL),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    deleted_at       TIMESTAMPTZ,
    like_count       INTEGER     NOT NULL DEFAULT 0,
    admin_removed_at TIMESTAMPTZ,
    CONSTRAINT stories_like_count_check CHECK ((like_count >= 0)),
    CONSTRAINT stories_view_count_check CHECK ((view_count >= 0)),
    PRIMARY KEY (id),
    FOREIGN KEY (media_asset_id) REFERENCES media_assets(id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE story_views (
    story_id  UUID        NOT NULL,
    viewer_id UUID        NOT NULL,
    viewed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (story_id, viewer_id),
    FOREIGN KEY (story_id) REFERENCES stories(id) ON DELETE CASCADE,
    FOREIGN KEY (viewer_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Story views (deduplicated per viewer)
-- Story likes, mirroring post_likes: composite primary key, and a counter on the parent row kept
-- by a trigger rather than by application code (V49).
CREATE TABLE story_likes (
    user_id    UUID        NOT NULL,
    story_id   UUID        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, story_id),
    FOREIGN KEY (story_id) REFERENCES stories(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: NOTIFICATIONS
-- ============================================================

CREATE TABLE notifications (
    id               UUID                  NOT NULL DEFAULT gen_random_uuid(),
    recipient_id     UUID                  NOT NULL,
    actor_id         UUID,
    type             notification_type     NOT NULL,
    -- Polymorphic target entity
    entity_type      VARCHAR(50),
    entity_id        UUID,
    read_at          TIMESTAMPTZ,
    created_at       TIMESTAMPTZ           NOT NULL DEFAULT NOW(),
    -- Denormalised so a notification can deep-link to the post without the client resolving
    -- entity_id first; null for a notification with no post (V47).
    post_id          UUID,
    message          TEXT,
    activity_at      TIMESTAMPTZ           NOT NULL DEFAULT NOW(),
    category         notification_category NOT NULL,
    aggregation_key  TEXT,
    is_group_open    BOOLEAN               NOT NULL DEFAULT FALSE,
    group_started_at TIMESTAMPTZ,
    actor_count      INTEGER               NOT NULL DEFAULT 0,
    actor_verified   BOOLEAN               NOT NULL DEFAULT FALSE,
    admin_action_id  UUID,
    deleted_at       TIMESTAMPTZ,
    CONSTRAINT chk_notifications_actor_count_nonnegative CHECK ((actor_count >= 0)),
    CONSTRAINT chk_notifications_open_group CHECK (((NOT is_group_open) OR ((aggregation_key IS NOT NULL) AND (group_started_at IS NOT NULL)))),
    PRIMARY KEY (id),
    FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (recipient_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: DIRECT MESSAGE / CHAT
-- ============================================================

-- Every conversation is 1-1; group conversations were removed (see
-- archived_group_conversations below). direct_pair_key is the two participants' user_id values
-- in sorted order, enforced unique so a pair can never hold two separate threads.
CREATE TABLE conversations (
    id              UUID        NOT NULL DEFAULT gen_random_uuid(),
    created_by      UUID,
    last_message_at TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    direct_pair_key TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
);

-- Members of a conversation
CREATE TABLE conversation_participants (
    conversation_id    UUID        NOT NULL,
    user_id            UUID        NOT NULL,
    joined_at          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    left_at            TIMESTAMPTZ,
    last_read_at       TIMESTAMPTZ,
    pinned_at          TIMESTAMPTZ,
    is_muted           BOOLEAN     NOT NULL DEFAULT FALSE,
    nickname           VARCHAR(50),
    is_manually_unread BOOLEAN     NOT NULL DEFAULT FALSE,
    PRIMARY KEY (conversation_id, user_id),
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Individual messages
CREATE TABLE messages (
    id               UUID         NOT NULL DEFAULT gen_random_uuid(),
    conversation_id  UUID         NOT NULL,
    sender_id        UUID,
    message_type     message_type NOT NULL DEFAULT 'text',
    content          TEXT,
    media_asset_id   UUID,
    -- Shared content references
    shared_post_id   UUID,
    shared_story_id  UUID,
    -- Thread reply
    reply_to_id      UUID,
    -- Sender-owned tombstone. Set together on the sender's own delete, which also clears content,
    -- so a sender deletion is irreversible by design.
    is_deleted       BOOLEAN      NOT NULL DEFAULT FALSE,
    deleted_at       TIMESTAMPTZ,
    created_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    -- Moderation-owned tombstone, independent of the pair above. Administrative removal sets it
    -- and preserves content so a restore can return the message; clearing it never undoes a
    -- sender deletion. A message is hidden when either tombstone is set.
    admin_removed_at TIMESTAMPTZ,
    PRIMARY KEY (id),
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE,
    FOREIGN KEY (media_asset_id) REFERENCES media_assets(id),
    FOREIGN KEY (reply_to_id) REFERENCES messages(id) ON DELETE SET NULL,
    FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (shared_post_id) REFERENCES posts(id) ON DELETE SET NULL,
    FOREIGN KEY (shared_story_id) REFERENCES stories(id) ON DELETE SET NULL
);

-- Write idempotency for message sends (V31). A retried send carrying the same key returns the
-- stored response rather than creating a second message; request_hash catches a key reused for a
-- different request.
CREATE TABLE message_write_idempotency (
    id              UUID        NOT NULL DEFAULT gen_random_uuid(),
    user_id         UUID        NOT NULL,
    idempotency_key VARCHAR(64) NOT NULL,
    request_hash    VARCHAR(64) NOT NULL,
    response_body   JSONB,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    UNIQUE (user_id, idempotency_key),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Snapshot of every group conversation, its members, and its messages, taken before group chat
-- was removed as a product decision. No foreign keys back into the live schema: these rows must
-- outlive the conversations they describe.
CREATE TABLE archived_group_conversations (
    id               UUID         NOT NULL,
    group_name       VARCHAR(100),
    group_avatar_url TEXT,
    created_by       UUID,
    last_message_at  TIMESTAMPTZ,
    created_at       TIMESTAMPTZ,
    archived_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id)
);

CREATE TABLE archived_group_participants (
    conversation_id UUID        NOT NULL,
    user_id         UUID        NOT NULL,
    is_admin        BOOLEAN,
    joined_at       TIMESTAMPTZ,
    left_at         TIMESTAMPTZ,
    last_read_at    TIMESTAMPTZ,
    archived_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (conversation_id, user_id)
);

CREATE TABLE archived_group_messages (
    id              UUID        NOT NULL,
    conversation_id UUID        NOT NULL,
    sender_id       UUID,
    message_type    TEXT,
    content         TEXT,
    media_asset_id  UUID,
    shared_post_id  UUID,
    shared_story_id UUID,
    reply_to_id     UUID,
    is_deleted      BOOLEAN,
    created_at      TIMESTAMPTZ,
    archived_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id)
);

-- ============================================================
-- MODULE: REPORT (Content Flagging)
-- ============================================================

CREATE TABLE reports (
    id                UUID          NOT NULL DEFAULT gen_random_uuid(),
    reporter_id       UUID          NOT NULL,
    report_type       report_type   NOT NULL,
    report_reason     report_reason NOT NULL,
    entity_id         UUID          NOT NULL,
    description       TEXT,
    status            report_status NOT NULL DEFAULT 'pending',
    reviewed_by       UUID,
    reviewed_at       TIMESTAMPTZ,
    resolution_note   TEXT,
    created_at        TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    -- Escalation to an administrator (V65). Columns rather than a join to admin_actions, so
    -- the queue read that shows the reason does not depend on the audit log.
    escalated_by      UUID,
    escalated_at      TIMESTAMPTZ,
    escalation_reason TEXT,
    PRIMARY KEY (id),
    FOREIGN KEY (escalated_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (reporter_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (reviewed_by) REFERENCES users(id) ON DELETE SET NULL
);

-- ============================================================
-- MODULE: METADATA CONFIG
-- ============================================================

-- System-wide configurable limits and TTL values
CREATE TABLE system_settings (
    key         VARCHAR(100) NOT NULL,
    value       TEXT         NOT NULL,
    description TEXT,
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (key)
);

-- Registry of notification types with display and toggle settings
-- type_key maps to values in the notification_type enum
CREATE TABLE notification_type_configs (
    type_key           VARCHAR(100) NOT NULL,
    display_name       VARCHAR(100) NOT NULL,
    template_key       VARCHAR(100),
    is_user_toggleable BOOLEAN      NOT NULL DEFAULT TRUE,
    is_enabled         BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (type_key)
);

-- Display metadata and policy configuration for each report reason
-- reason_key maps to values in the report_reason enum
-- applies_to: empty array means applies to all report types
CREATE TABLE report_reason_configs (
    reason_key   VARCHAR(100) NOT NULL,
    display_name VARCHAR(100) NOT NULL,
    description  TEXT,
    applies_to VARCHAR(50)[] DEFAULT '{}'::VARCHAR[] NOT NULL,
    is_enabled   BOOLEAN      NOT NULL DEFAULT TRUE,
    sort_order   SMALLINT     NOT NULL DEFAULT 0,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (reason_key)
);

-- Registry of admin moderation actions with behavioral flags
-- action_key maps to values in the admin_action_type enum
CREATE TABLE moderation_action_configs (
    action_key      VARCHAR(100) NOT NULL,
    display_name    VARCHAR(100) NOT NULL,
    requires_reason BOOLEAN      NOT NULL DEFAULT FALSE,
    is_reversible   BOOLEAN      NOT NULL DEFAULT TRUE,
    is_enabled      BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (action_key)
);

-- Feature enable/disable control with optional environment scoping
CREATE TABLE feature_flags (
    flag_key    VARCHAR(100) NOT NULL,
    is_enabled  BOOLEAN      NOT NULL DEFAULT FALSE,
    description TEXT,
    environment VARCHAR(20)  NOT NULL DEFAULT 'all'::VARCHAR,
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT feature_flags_environment_check CHECK (((environment)::TEXT = ANY ((ARRAY['all'::VARCHAR, 'dev'::VARCHAR, 'staging'::VARCHAR, 'prod'::VARCHAR])::TEXT[]))),
    PRIMARY KEY (flag_key)
);

CREATE TABLE support_category_configs (
    category_key       VARCHAR(100) NOT NULL,
    display_name       VARCHAR(100) NOT NULL,
    description        TEXT,
    is_appeal          BOOLEAN      NOT NULL DEFAULT FALSE,
    allows_public_form BOOLEAN      NOT NULL DEFAULT TRUE,
    is_enabled         BOOLEAN      NOT NULL DEFAULT TRUE,
    sort_order         SMALLINT     NOT NULL DEFAULT 0,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (category_key)
);

CREATE TABLE verification_categories (
    category_key VARCHAR(50)  NOT NULL,
    display_name VARCHAR(100) NOT NULL,
    covers       TEXT         NOT NULL,
    icon_key     VARCHAR(50)  NOT NULL,
    is_enabled   BOOLEAN      NOT NULL DEFAULT TRUE,
    sort_order   SMALLINT     NOT NULL DEFAULT 0,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (category_key)
);

-- ============================================================
-- MODULE: ADMIN (Moderation Audit Log)
-- ============================================================

CREATE TABLE admin_actions (
    id                 UUID              NOT NULL DEFAULT gen_random_uuid(),
    admin_id           UUID,
    action_type        admin_action_type NOT NULL,
    target_user_id     UUID,
    target_entity_type VARCHAR(50),
    target_entity_id   UUID,
    report_id          UUID,
    reason             TEXT,
    metadata           JSONB,
    created_at         TIMESTAMPTZ       NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    FOREIGN KEY (admin_id) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (report_id) REFERENCES reports(id) ON DELETE SET NULL,
    FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE SET NULL
);

-- Warnings a moderator issues against an account. Three active warnings produce a strike.
-- admin_action_id is NOT NULL: every row here is explained by an audit row written in the same
-- transaction, and the foreign key is what makes that impossible to skip.
-- reason_key references report_reason_configs, which is that table's only runtime reader.
CREATE TABLE user_warnings (
    id              UUID        NOT NULL DEFAULT gen_random_uuid(),
    user_id         UUID        NOT NULL,
    issued_by       UUID,
    reason_key      VARCHAR(50) NOT NULL,
    note            TEXT        NOT NULL,
    admin_action_id UUID        NOT NULL,
    revoked_at      TIMESTAMPTZ,
    revoked_by      UUID,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT user_warnings_note_not_blank CHECK ((length(btrim(note)) > 0)),
    PRIMARY KEY (id),
    FOREIGN KEY (admin_action_id) REFERENCES admin_actions(id),
    FOREIGN KEY (issued_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (reason_key) REFERENCES report_reason_configs(reason_key),
    FOREIGN KEY (revoked_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Strikes, the consequence three active warnings produce.
-- strike_number is CHECK (>= 1), deliberately not capped at 3: an administrator may unban a
-- strike-3 account by hand, and a cap would make that account's next strike fail to insert.
-- Strike 3 and every strike above it carry the same consequence, so a cap would buy nothing.
CREATE TABLE user_strikes (
    id              UUID        NOT NULL DEFAULT gen_random_uuid(),
    user_id         UUID        NOT NULL,
    strike_number   SMALLINT    NOT NULL,
    triggered_by    UUID,
    admin_action_id UUID        NOT NULL,
    revoked_at      TIMESTAMPTZ,
    revoked_by      UUID,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT user_strikes_strike_number_check CHECK ((strike_number >= 1)),
    PRIMARY KEY (id),
    FOREIGN KEY (admin_action_id) REFERENCES admin_actions(id),
    FOREIGN KEY (revoked_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (triggered_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Pre-aggregated platform statistics (V70).
-- Written only by the collection and roll-up jobs, never from a request path. A gauge is an
-- absolute snapshot bounded by the end of its bucket; a flow is a direct count over the bucket
-- window and is never derived by subtracting consecutive gauges. GROUP BY produces no row for an
-- empty group, so a dimension nobody holds in a bucket has no row rather than a row holding zero,
-- and every reader treats a missing dimension as zero. The composite primary key with
-- ON CONFLICT DO UPDATE is what keeps a double run harmless rather than duplicative.
CREATE TABLE platform_stats (
    bucket_start TIMESTAMPTZ      NOT NULL,
    granularity  stat_granularity NOT NULL,
    metric_key   VARCHAR(64)      NOT NULL,
    dimension    VARCHAR(64)      NOT NULL DEFAULT ''::VARCHAR,
    value        BIGINT           NOT NULL,
    computed_at  TIMESTAMPTZ      NOT NULL DEFAULT NOW(),
    PRIMARY KEY (bucket_start, granularity, metric_key, dimension)
);

-- ============================================================
-- MODULE: SUPPORT (Tickets, Appeals, Verification)
-- ============================================================

CREATE TABLE support_tickets (
    id                UUID                  NOT NULL DEFAULT gen_random_uuid(),
    user_id           UUID,
    contact_email     VARCHAR(255)          NOT NULL,
    category          support_category      NOT NULL,
    subject           VARCHAR(200)          NOT NULL,
    body              TEXT                  NOT NULL,
    status            support_ticket_status NOT NULL DEFAULT 'open',
    source            support_source        NOT NULL,
    admin_action_id   UUID,
    assigned_to       UUID,
    assigned_at       TIMESTAMPTZ,
    staff_response    TEXT,
    internal_note     TEXT,
    responded_by      UUID,
    responded_at      TIMESTAMPTZ,
    escalated_by      UUID,
    escalated_at      TIMESTAMPTZ,
    escalation_reason TEXT,
    created_at        TIMESTAMPTZ           NOT NULL DEFAULT NOW(),
    updated_at        TIMESTAMPTZ           NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    FOREIGN KEY (admin_action_id) REFERENCES admin_actions(id) ON DELETE SET NULL,
    FOREIGN KEY (assigned_to) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (escalated_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (responded_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE user_verifications (
    id                UUID                          NOT NULL DEFAULT gen_random_uuid(),
    user_id           UUID                          NOT NULL,
    category_key      VARCHAR(50)                   NOT NULL,
    request_ticket_id UUID,
    granted_by        UUID,
    granted_at        TIMESTAMPTZ                   NOT NULL DEFAULT NOW(),
    granted_action_id UUID,
    revoked_at        TIMESTAMPTZ,
    revoked_by        UUID,
    revocation_reason TEXT,
    revocation_actor  verification_revocation_actor,
    revoked_action_id UUID,
    CONSTRAINT user_verifications_revocation_pair CHECK ((((revoked_at IS NULL) AND (revocation_actor IS NULL) AND (revoked_by IS NULL) AND (revocation_reason IS NULL) AND (revoked_action_id IS NULL)) OR ((revoked_at IS NOT NULL) AND (revocation_actor IS NOT NULL)))),
    CONSTRAINT user_verifications_system_has_no_actor CHECK (((revocation_actor IS DISTINCT FROM 'system'::verification_revocation_actor) OR (revoked_by IS NULL))),
    PRIMARY KEY (id),
    FOREIGN KEY (category_key) REFERENCES verification_categories(category_key),
    FOREIGN KEY (granted_action_id) REFERENCES admin_actions(id) ON DELETE SET NULL,
    FOREIGN KEY (granted_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (request_ticket_id) REFERENCES support_tickets(id) ON DELETE SET NULL,
    FOREIGN KEY (revoked_action_id) REFERENCES admin_actions(id) ON DELETE SET NULL,
    FOREIGN KEY (revoked_by) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE verification_requests (
    ticket_id                 UUID         NOT NULL,
    user_id                   UUID         NOT NULL,
    category_key              VARCHAR(50)  NOT NULL,
    claimed_name              VARCHAR(100) NOT NULL,
    evidence_website          TEXT,
    evidence_other_profile    TEXT,
    evidence_email_domain     TEXT,
    evidence_published_work   TEXT,
    evidence_press            TEXT,
    evidence_official_listing TEXT,
    evidence_note             TEXT,
    evidence_field_count      SMALLINT     NOT NULL,
    created_at                TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT verification_requests_evidence_count_bound CHECK ((evidence_field_count <= 7)),
    CONSTRAINT verification_requests_min_evidence CHECK ((evidence_field_count >= 3)),
    PRIMARY KEY (ticket_id),
    FOREIGN KEY (category_key) REFERENCES verification_categories(category_key),
    FOREIGN KEY (ticket_id) REFERENCES support_tickets(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: MAIL
-- ============================================================

CREATE TABLE email_deliveries (
    id                  UUID                  NOT NULL DEFAULT gen_random_uuid(),
    recipient_user_id   UUID,
    recipient_email     VARCHAR(255)          NOT NULL,
    template_key        VARCHAR(100)          NOT NULL,
    admin_action_id     UUID,
    status              email_delivery_status NOT NULL DEFAULT 'pending',
    provider_message_id VARCHAR(255),
    error_text          TEXT,
    attempt_count       INTEGER               NOT NULL DEFAULT 0,
    created_at          TIMESTAMPTZ           NOT NULL DEFAULT NOW(),
    sent_at             TIMESTAMPTZ,
    CONSTRAINT email_deliveries_attempt_count_check CHECK ((attempt_count >= 0)),
    PRIMARY KEY (id),
    FOREIGN KEY (admin_action_id) REFERENCES admin_actions(id),
    FOREIGN KEY (recipient_user_id) REFERENCES users(id) ON DELETE SET NULL
);

-- ============================================================
-- MODULE: INTEREST TAXONOMY
-- ============================================================

-- Interest taxonomy (e.g. Fashion > Streetwear)
CREATE TABLE categories (
    id         UUID         NOT NULL DEFAULT gen_random_uuid(),
    name       VARCHAR(100) NOT NULL,
    slug       VARCHAR(100) NOT NULL,
    parent_id  UUID,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (id),
    UNIQUE (name),
    UNIQUE (slug),
    FOREIGN KEY (parent_id) REFERENCES categories(id)
);

-- User interest weights (updated by ML jobs or explicit selection)
CREATE TABLE user_interests (
    user_id     UUID         NOT NULL,
    category_id UUID         NOT NULL,
    score       NUMERIC(5,2) NOT NULL DEFAULT 1.0,
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, category_id),
    FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- Post categorisation (assigned during upload or by ML classifier)
CREATE TABLE post_categories (
    post_id     UUID         NOT NULL,
    category_id UUID         NOT NULL,
    confidence  NUMERIC(4,3) NOT NULL DEFAULT 1.0,
    PRIMARY KEY (post_id, category_id),
    FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE,
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
);

-- User tags within a post image
CREATE TABLE post_user_tags (
    post_id        UUID         NOT NULL,
    tagged_user_id UUID         NOT NULL,
    media_asset_id UUID,
    x_position     NUMERIC(5,2),
    y_position     NUMERIC(5,2),
    PRIMARY KEY (post_id, tagged_user_id),
    FOREIGN KEY (media_asset_id) REFERENCES media_assets(id),
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE,
    FOREIGN KEY (tagged_user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: RECOMMENDATION SYSTEM & USER BEHAVIOR
-- ============================================================

-- Raw event stream for user behavior
-- Partitioned by month: high-volume, append-only, analytics-friendly
CREATE TABLE user_events (
    id          UUID        NOT NULL DEFAULT gen_random_uuid(),
    user_id     UUID        NOT NULL,
    session_id  UUID,
    event_type  event_type  NOT NULL,
    entity_type VARCHAR(50),
    entity_id   UUID,
    metadata    JSONB,
    ip_address  INET,
    user_agent  TEXT,
    platform    VARCHAR(10),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT user_events_platform_check CHECK (((platform)::TEXT = ANY ((ARRAY['ios'::VARCHAR, 'android'::VARCHAR, 'web'::VARCHAR])::TEXT[]))),
    PRIMARY KEY (id, created_at),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) PARTITION BY RANGE (created_at);

-- Aggregated post interaction scores (updated by background scheduler)
-- Powers feed ranking and Explore page recommendation
CREATE TABLE post_interaction_scores (
    post_id          UUID          NOT NULL,
    view_score       NUMERIC(10,4) NOT NULL DEFAULT 0,
    engagement_score NUMERIC(10,4) NOT NULL DEFAULT 0,
    recency_score    NUMERIC(10,4) NOT NULL DEFAULT 0,
    total_score      NUMERIC(10,4) NOT NULL DEFAULT 0,
    computed_at      TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    PRIMARY KEY (post_id),
    FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
);

-- User-to-user similarity for collaborative filtering (populated by ML jobs)
-- Constraint: store only (min_id, max_id) to avoid (A,B) / (B,A) duplication
CREATE TABLE user_similarity (
    user_id_a        UUID         NOT NULL,
    user_id_b        UUID         NOT NULL,
    similarity_score NUMERIC(6,4) NOT NULL,
    computed_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT user_similarity_check CHECK ((user_id_a < user_id_b)),
    CONSTRAINT user_similarity_similarity_score_check CHECK (((similarity_score >= (0)::NUMERIC) AND (similarity_score <= (1)::NUMERIC))),
    PRIMARY KEY (user_id_a, user_id_b),
    FOREIGN KEY (user_id_a) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id_b) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE user_hashtag_affinity (
    user_id      UUID          NOT NULL,
    hashtag_id   UUID          NOT NULL,
    score        NUMERIC(10,8) NOT NULL,
    weight       NUMERIC(14,6) NOT NULL,
    event_count  INTEGER       NOT NULL,
    window_start TIMESTAMPTZ   NOT NULL,
    window_end   TIMESTAMPTZ   NOT NULL,
    computed_at  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    CONSTRAINT user_hashtag_affinity_event_count_check CHECK ((event_count >= 0)),
    CONSTRAINT user_hashtag_affinity_score_check CHECK (((score >= (0)::NUMERIC) AND (score <= (1)::NUMERIC))),
    CONSTRAINT user_hashtag_affinity_weight_check CHECK ((weight >= (0)::NUMERIC)),
    CONSTRAINT user_hashtag_affinity_window_order CHECK ((window_end > window_start)),
    PRIMARY KEY (user_id, hashtag_id),
    FOREIGN KEY (hashtag_id) REFERENCES hashtags(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE user_suggestions (
    user_id      UUID          NOT NULL,
    suggested_id UUID          NOT NULL,
    rank         SMALLINT      NOT NULL,
    score        NUMERIC(12,8) NOT NULL,
    sources      TEXT          NOT NULL,
    computed_at  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    CONSTRAINT user_suggestions_not_self CHECK ((user_id <> suggested_id)),
    CONSTRAINT user_suggestions_rank_positive CHECK ((rank > 0)),
    PRIMARY KEY (user_id, suggested_id),
    FOREIGN KEY (suggested_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

CREATE TABLE suggestion_dismissals (
    user_id      UUID        NOT NULL,
    dismissed_id UUID        NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT suggestion_dismissals_not_self CHECK ((user_id <> dismissed_id)),
    PRIMARY KEY (user_id, dismissed_id),
    FOREIGN KEY (dismissed_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);

-- ============================================================
-- MODULE: COMMON / OUTBOX
-- ============================================================

CREATE TABLE outbox_events (
    id             UUID         NOT NULL DEFAULT gen_random_uuid(),
    event_id       UUID         NOT NULL,
    aggregate_type VARCHAR(100) NOT NULL,
    aggregate_id   UUID         NOT NULL,
    event_type     VARCHAR(150) NOT NULL,
    routing_key    VARCHAR(150) NOT NULL,
    payload        JSONB        NOT NULL,
    status         VARCHAR(20)  NOT NULL DEFAULT 'PENDING'::VARCHAR,
    attempt_count  INTEGER      NOT NULL DEFAULT 0,
    next_retry_at  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    last_error     TEXT,
    created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    published_at   TIMESTAMPTZ,
    claim_id       UUID,
    claimed_at     TIMESTAMPTZ,
    claimed_until  TIMESTAMPTZ,
    CONSTRAINT chk_outbox_events_processing_claim CHECK ((((status)::TEXT <> 'PROCESSING'::TEXT) OR ((claim_id IS NOT NULL) AND (claimed_at IS NOT NULL) AND (claimed_until IS NOT NULL) AND (claimed_until > claimed_at)))),
    CONSTRAINT outbox_events_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT outbox_events_check CHECK (((((status)::TEXT = 'PUBLISHED'::TEXT) AND (published_at IS NOT NULL)) OR (((status)::TEXT <> 'PUBLISHED'::TEXT) AND (published_at IS NULL)))),
    CONSTRAINT outbox_events_status_check CHECK (((status)::TEXT = ANY ((ARRAY['PENDING'::VARCHAR, 'PROCESSING'::VARCHAR, 'PUBLISHED'::VARCHAR, 'DEAD'::VARCHAR])::TEXT[]))),
    PRIMARY KEY (id),
    UNIQUE (event_id)
);

