-- indexes on users
CREATE INDEX idx_users_created_at ON users USING btree (created_at DESC);
CREATE INDEX idx_users_email ON users USING btree (email);
-- Administrative account surface (V57). Built CONCURRENTLY by the migration; plain here because
-- this file describes the final state rather than how to reach it on a live database.
-- Email had no trigram index before this, so an administrator searching by address paid a parallel
-- sequential scan of the whole table: measured at 77 ms against 200,000 rows, 0.3 ms with it.
CREATE INDEX idx_users_email_trgm ON users USING gin (email gin_trgm_ops);
CREATE INDEX idx_users_fts ON users USING gin (to_tsvector('simple'::regconfig, (((COALESCE(username, ''::VARCHAR))::TEXT || ' '::TEXT) || (COALESCE(display_name, ''::VARCHAR))::TEXT)));
-- Role-filtered account listing (V72). The rare role is the decisive case: an administrator
-- filters by moderator or admin precisely because those are the accounts worth looking at, and
-- without this the plan discards rows in proportion to the whole table rather than to the role.
CREATE INDEX idx_users_role_created ON users USING btree (role, created_at DESC, id DESC);
CREATE INDEX idx_users_status ON users USING btree (status) WHERE (deleted_at IS NULL);
-- Turns a status-filtered account page from an Incremental Sort that discards over a thousand rows
-- per page into a single index seek that carries the keyset tiebreaker.
CREATE INDEX idx_users_status_created ON users USING btree (status, created_at DESC, id DESC);
-- Partial, so an indefinite suspension (null deadline) is absent from the index rather than
-- filtered out of it. Bounds the reinstatement sweep's candidate scan.
CREATE INDEX idx_users_suspended_until ON users USING btree (suspended_until) WHERE (suspended_until IS NOT NULL);
-- users
CREATE INDEX idx_users_username ON users USING btree (username) WHERE (deleted_at IS NULL);
CREATE INDEX idx_users_username_trgm ON users USING gin (username gin_trgm_ops);
CREATE INDEX idx_users_verified_followers ON users USING btree (verified_category, follower_count DESC) WHERE ((is_verified = true) AND (deleted_at IS NULL));
-- Same table-wide shape and rationale as idx_users_username_lower, applied to email: soft delete
-- does not release an email either, and email identity is case-insensitive per RFC 5321 and every
-- major mail provider's practice. users_email_key (raw UNIQUE column constraint above) is retained
-- as a structural guard and is implied by this index.
CREATE UNIQUE INDEX idx_users_email_lower ON users USING btree (lower((email)::TEXT));
-- Table-wide (not partial on deleted_at) so a soft-deleted account's username stays reserved,
-- matching the documented soft-delete retention policy; users_username_key (raw UNIQUE column
-- constraint above) is retained as a structural guard and is implied by this index.
CREATE UNIQUE INDEX idx_users_username_lower ON users USING btree (lower((username)::TEXT));

