-- ============================================================
-- FUNCTIONS
-- ============================================================

-- Comment like_count
CREATE FUNCTION fn_comment_like_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE comments SET like_count = like_count + 1 WHERE id = NEW.comment_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE comments SET like_count = GREATEST(like_count - 1, 0) WHERE id = OLD.comment_id;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

-- Comment reply_count (on parent)
CREATE FUNCTION fn_comment_reply_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    was_visible BOOLEAN;
    now_visible BOOLEAN;
BEGIN
    IF TG_OP = 'INSERT' AND NEW.parent_id IS NOT NULL THEN
        IF NEW.deleted_at IS NULL AND NEW.admin_removed_at IS NULL THEN
            UPDATE comments SET reply_count = reply_count + 1 WHERE id = NEW.parent_id;
        END IF;
    ELSIF TG_OP = 'DELETE' AND OLD.parent_id IS NOT NULL THEN
        IF OLD.deleted_at IS NULL AND OLD.admin_removed_at IS NULL THEN
            UPDATE comments SET reply_count = GREATEST(reply_count - 1, 0) WHERE id = OLD.parent_id;
        END IF;
    ELSIF TG_OP = 'UPDATE' AND NEW.parent_id IS NOT NULL THEN
        was_visible := OLD.deleted_at IS NULL AND OLD.admin_removed_at IS NULL;
        now_visible := NEW.deleted_at IS NULL AND NEW.admin_removed_at IS NULL;
        IF was_visible AND NOT now_visible THEN
            UPDATE comments SET reply_count = GREATEST(reply_count - 1, 0) WHERE id = NEW.parent_id;
        ELSIF now_visible AND NOT was_visible THEN
            UPDATE comments SET reply_count = reply_count + 1 WHERE id = NEW.parent_id;
        END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

-- Update conversations.last_message_at on new message
CREATE FUNCTION fn_conversation_last_message() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE conversations
    SET last_message_at = NEW.created_at,
        updated_at      = NEW.created_at
    WHERE id = NEW.conversation_id;
    RETURN NEW;
END;
$$;

-- Follow counter maintenance. Both users rows are locked in id order before either is written,
-- so two people following each other back at the same instant queue behind each other instead
-- of deadlocking on the opposite lock order.
CREATE FUNCTION fn_follow_counts() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    follower_key  UUID;
    following_key UUID;
BEGIN
    IF TG_OP = 'DELETE' THEN
        follower_key  := OLD.follower_id;
        following_key := OLD.following_id;
    ELSE
        follower_key  := NEW.follower_id;
        following_key := NEW.following_id;
    END IF;

    -- Both rows locked in id order before either is written, so the two directions of a pair can
    -- never hold one lock each and wait on the other.
    PERFORM 1 FROM users
    WHERE id IN (follower_key, following_key)
    ORDER BY id
    FOR NO KEY UPDATE;

    IF TG_OP = 'INSERT' AND NEW.status = 'accepted' THEN
        UPDATE users SET following_count = following_count + 1 WHERE id = NEW.follower_id;
        UPDATE users SET follower_count  = follower_count  + 1 WHERE id = NEW.following_id;

    ELSIF TG_OP = 'DELETE' AND OLD.status = 'accepted' THEN
        UPDATE users SET following_count = GREATEST(following_count - 1, 0) WHERE id = OLD.follower_id;
        UPDATE users SET follower_count  = GREATEST(follower_count  - 1, 0) WHERE id = OLD.following_id;

    ELSIF TG_OP = 'UPDATE' THEN
        IF OLD.status <> 'accepted' AND NEW.status = 'accepted' THEN
            UPDATE users SET following_count = following_count + 1 WHERE id = NEW.follower_id;
            UPDATE users SET follower_count  = follower_count  + 1 WHERE id = NEW.following_id;
        ELSIF OLD.status = 'accepted' AND NEW.status <> 'accepted' THEN
            UPDATE users SET following_count = GREATEST(following_count - 1, 0) WHERE id = NEW.follower_id;
            UPDATE users SET follower_count  = GREATEST(follower_count  - 1, 0) WHERE id = NEW.following_id;
        END IF;
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;

-- Hashtag post_count
CREATE FUNCTION fn_hashtag_post_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE hashtags SET post_count = post_count + 1 WHERE id = NEW.hashtag_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE hashtags SET post_count = GREATEST(post_count - 1, 0) WHERE id = OLD.hashtag_id;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

