-- Post comment_count
CREATE FUNCTION fn_post_comment_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    was_visible BOOLEAN;
    now_visible BOOLEAN;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.deleted_at IS NULL AND NEW.admin_removed_at IS NULL THEN
            UPDATE posts SET comment_count = comment_count + 1 WHERE id = NEW.post_id;
        END IF;
    ELSIF TG_OP = 'DELETE' THEN
        IF OLD.deleted_at IS NULL AND OLD.admin_removed_at IS NULL THEN
            UPDATE posts SET comment_count = GREATEST(comment_count - 1, 0) WHERE id = OLD.post_id;
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        was_visible := OLD.deleted_at IS NULL AND OLD.admin_removed_at IS NULL;
        now_visible := NEW.deleted_at IS NULL AND NEW.admin_removed_at IS NULL;
        IF was_visible AND NOT now_visible THEN
            UPDATE posts SET comment_count = GREATEST(comment_count - 1, 0) WHERE id = NEW.post_id;
        ELSIF now_visible AND NOT was_visible THEN
            UPDATE posts SET comment_count = comment_count + 1 WHERE id = NEW.post_id;
        END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

-- Post count on users
CREATE FUNCTION fn_post_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.status = 'published' AND NEW.deleted_at IS NULL THEN
        UPDATE users SET post_count = post_count + 1 WHERE id = NEW.user_id;

    ELSIF TG_OP = 'DELETE' AND OLD.status = 'published' AND OLD.deleted_at IS NULL THEN
        UPDATE users SET post_count = GREATEST(post_count - 1, 0) WHERE id = OLD.user_id;

    ELSIF TG_OP = 'UPDATE' THEN
        IF (OLD.status <> 'published' OR OLD.deleted_at IS NOT NULL)
            AND NEW.status = 'published' AND NEW.deleted_at IS NULL THEN
            UPDATE users SET post_count = post_count + 1 WHERE id = NEW.user_id;
        ELSIF OLD.status = 'published' AND OLD.deleted_at IS NULL
            AND (NEW.status <> 'published' OR NEW.deleted_at IS NOT NULL) THEN
            UPDATE users SET post_count = GREATEST(post_count - 1, 0) WHERE id = NEW.user_id;
        END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

