CREATE FUNCTION fn_sync_user_verification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    affected UUID;
BEGIN
    affected := COALESCE(NEW.user_id, OLD.user_id);
    UPDATE users u
       SET is_verified = v.active IS NOT NULL,
           verified_category = v.active
      FROM (
          SELECT (SELECT category_key
                    FROM user_verifications
                   WHERE user_id = affected AND revoked_at IS NULL
                   ORDER BY granted_at DESC
                   LIMIT 1) AS active
      ) v
     WHERE u.id = affected;
    RETURN NULL;
END;
$$;

-- Generic updated_at updater
CREATE FUNCTION fn_update_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;

SET default_tablespace = '';

SET default_table_access_method = heap;

