-- ============================================================
-- VIEWS
-- ============================================================

-- Active (non-expired, non-deleted) stories
CREATE VIEW active_stories AS
 SELECT s.id,
    s.user_id,
    s.media_asset_id,
    s.story_type,
    s.caption,
    s.view_count,
    s.expires_at,
    s.created_at,
    s.deleted_at,
    s.like_count,
    s.admin_removed_at,
    u.username,
    u.avatar_url
   FROM (stories s
     JOIN users u ON (((u.id = s.user_id) AND (u.deleted_at IS NULL))))
  WHERE ((s.deleted_at IS NULL) AND (s.admin_removed_at IS NULL) AND (s.expires_at > NOW()));

-- Pending follow requests (for private accounts)
CREATE VIEW pending_follow_requests AS
 SELECT f.follower_id,
    f.following_id,
    f.status,
    f.created_at,
    follower.username AS follower_username,
    follower.avatar_url AS follower_avatar
   FROM (follows f
     JOIN users follower ON (((follower.id = f.follower_id) AND (follower.deleted_at IS NULL))))
  WHERE (f.status = 'pending'::follow_status);

-- Pending moderation reports
CREATE VIEW pending_reports AS
 SELECT r.id,
    r.reporter_id,
    r.report_type,
    r.report_reason,
    r.entity_id,
    r.description,
    r.status,
    r.reviewed_by,
    r.reviewed_at,
    r.resolution_note,
    r.created_at,
    reporter.username AS reporter_username
   FROM (reports r
     JOIN users reporter ON (((reporter.id = r.reporter_id) AND (reporter.deleted_at IS NULL))))
  WHERE (r.status = 'pending'::report_status)
  ORDER BY r.created_at;

-- ============================================================
-- OBJECT COMMENTS
-- ============================================================

-- `COMMENT ON` text stored in the database itself, written by the migrations. It is
-- part of the schema, so it is reproduced verbatim rather than paraphrased.

COMMENT ON TYPE email_delivery_status IS 'Observable outcomes of one send attempt. pending is written before the provider call; sent carries a provider_message_id; failed carries error_text; throttled means the per-recipient window rejected it before any call; skipped means the recipient was ineligible, such as a soft-deleted account.';

COMMENT ON TYPE support_category IS 'What the ticket is about. The four appeal_ values are the restricted set: only an administrator may respond to or close one, because unban, unsuspend, revoke_warning and revoke_strike are all administrator-only actions and a moderator closing an appeal would be issuing a verdict they cannot execute.';

COMMENT ON TYPE support_source IS 'How the ticket arrived. signed_link means a single-use token from a moderation mail authorised exactly this one ticket against one audit row; it never minted a session.';

COMMENT ON TYPE support_ticket_status IS 'pending_confirmation belongs to the public form alone: the row exists but is invisible to staff until the submitter proves control of the address. answered and rejected are terminal, and terminal is what the one-open-ticket guard treats as closed.';

COMMENT ON COLUMN stories.admin_removed_at IS 'Set by administrative removal; independent of the owner-owned deleted_at. A story is hidden when either column is set, and expires_at continues to decide visibility independently of both.';

COMMENT ON COLUMN users.verified_category IS 'Denormalised from the account''s active user_verifications row by trg_user_verification_sync. Never written by application code. Null exactly when is_verified is false.';

COMMENT ON TABLE archived_mail_campaign_recipients IS 'Withdrawn with the mail campaign feature in V114. status is TEXT because mail_campaign_recipient_status was dropped in the same migration.';

COMMENT ON TABLE archived_mail_campaigns IS 'Withdrawn with the mail campaign feature in V114. status is TEXT because mail_campaign_status was dropped in the same migration.';

COMMENT ON TABLE archived_mail_templates IS 'Withdrawn with the mail campaign feature in V114. Retained so a later reader can see what the three seeded Markdown samples held.';

COMMENT ON COLUMN comments.edited_at IS 'When the content was last changed by its author. NULL means never edited. Written by application code on the edit path only; unlike updated_at, no trigger touches it, so a like or a reply leaves it alone.';

COMMENT ON COLUMN comments.admin_removed_at IS 'Set by administrative removal; independent of the author-owned deleted_at. A comment is hidden when either column is set, and clearing this one never undoes the author''s own deletion.';

COMMENT ON COLUMN email_deliveries.recipient_user_id IS 'Nullable and ON DELETE SET NULL so a hard-deleted account does not erase the record that mail was sent to it; recipient_email preserves the destination.';

COMMENT ON COLUMN email_deliveries.admin_action_id IS 'The moderation decision this delivery announces, or NULL for mail with no audit row behind it, such as auth mail.';

COMMENT ON COLUMN email_deliveries.provider_message_id IS 'Identifier returned by the provider on acceptance. NULL for every status other than sent.';

COMMENT ON COLUMN email_deliveries.attempt_count IS 'Provider calls made for this row. Stays 0 for a row that never reached a call, which is what separates a throttled or skipped send from one the provider rejected.';

COMMENT ON COLUMN hashtags.pinned_at IS 'When an administrator pinned this hashtag platform-wide; NULL means not pinned.';

COMMENT ON COLUMN messages.admin_removed_at IS 'Set by administrative removal; independent of the sender-owned is_deleted/deleted_at pair. Content is preserved so a restore can return the message.';

COMMENT ON TABLE notifications_pre_overhaul_archive IS 'Every notifications row as it stood before V116-V123. Read-only; drop in a later release.';

COMMENT ON TABLE suggestion_dismissals IS 'Permanent per-viewer suppression of one account from people-you-may-know. Never a block: it changes no other surface.';

COMMENT ON COLUMN support_tickets.user_id IS 'Nullable: the public form produces a ticket before any account is resolved, and ON DELETE SET NULL keeps the ticket after a hard delete. contact_email is the durable channel.';

COMMENT ON COLUMN support_tickets.contact_email IS 'Where the response goes. Captured even for an authenticated ticket, because the account may be banned and this address is then the only channel that reaches the person.';

COMMENT ON COLUMN support_tickets.admin_action_id IS 'The audit row this ticket appeals against, populated when the ticket arrived through a signed link. Also the input to the conflict-of-interest rule: the staff member who wrote that row may not act on this ticket.';

COMMENT ON COLUMN support_tickets.assigned_to IS 'Set by a guarded update whose predicate re-checks that the ticket is still unassigned, so a second claimer is refused rather than silently overwriting the first.';

COMMENT ON COLUMN support_tickets.internal_note IS 'Staff-only. Never rendered into any user-facing response and never carried into any mail. staff_response is the field that reaches the user.';

COMMENT ON TABLE user_hashtag_affinity IS 'Per-user hashtag interest scores derived from user_events joined to post_hashtags over a bounded window. Rebuildable: truncating it costs only the next scheduled recompute.';

COMMENT ON COLUMN user_hashtag_affinity.score IS 'Normalised share of the user total, in [0,1]; comparable across users of different activity volumes.';

COMMENT ON COLUMN user_settings.suggestible IS 'False when the account has asked not to be offered in other people''s suggestions. Applied at read time, not only in the precompute job.';

COMMENT ON TABLE user_suggestions IS 'Precomputed people-you-may-know candidates. Rebuildable from source at any time. Every exclusion rule is re-applied at read time, because a twelve-hour cycle would otherwise keep suggesting an account the viewer followed this morning.';

COMMENT ON COLUMN user_verifications.revocation_actor IS 'moderator when a person decided, system when an account status change swept the badge away. A status-driven revocation is not a verdict and must not read as one.';

COMMENT ON COLUMN verification_categories.covers IS 'The occupations this category is meant to cover, shown to the requester so they can pick without guessing. Never parsed.';

COMMENT ON TABLE verification_requests IS 'The structured half of a verification_request support ticket. Immutable after insert: it records what was asked for, and the ticket beside it records what happened next.';

